#' Residual Cancer Burden (RCB)
#'
#' Computes the Residual Cancer Burden (RCB) index and class (Symmans et al., 
#' 2007) from the standard post-neoadjuvant pathology variables: the two 
#' dimensions of the primary tumour bed, overall cancer cellularity, the 
#' in-situ fraction, the number of positive lymph nodes, and the diameter of 
#' the largest nodal metastasis. The continuous index is classified into RCB-0 
#' (pathologic complete response), RCB-I (minimal), RCB-II (moderate), and 
#' RCB-III (extensive) residual disease using the established cut points (1.36 
#' and 3.28). Works on a cohort (one row per patient) or as a single-case 
#' calculator, and can optionally relate RCB class to a survival outcome.
#' 
#'
#' @examples
#' \donttest{
#' residualcancerburden(
#'     data = mydata,
#'     d1 = "tumor_dim1", d2 = "tumor_dim2",
#'     cellularity = "pct_cellularity", cis = "pct_insitu",
#'     positiveNodes = "n_pos_nodes", metSize = "largest_met_mm")
#'}
#' @param data The data as a data frame (one row per patient in cohort mode).
#' @param inputMode Compute RCB for every row using data variables, or for a
#'   single entered case.
#' @param d1 First bidimensional diameter of the primary tumour bed (mm).
#' @param d2 Second bidimensional diameter of the primary tumour bed (mm).
#' @param cellularity Overall percentage of the tumour bed area that is
#'   carcinoma (0-100).
#' @param cis Percentage of the carcinoma that is in-situ disease (0-100).
#'   Defaults to 0.
#' @param positiveNodes Number of regional lymph nodes containing metastatic
#'   carcinoma.
#' @param metSize Diameter of the largest nodal metastasis (mm). Defaults to
#'   0.
#' @param mD1 Single-case first tumour-bed dimension (mm).
#' @param mD2 Single-case second tumour-bed dimension (mm).
#' @param mCellularity Single-case overall cellularity (percent).
#' @param mCis Single-case in-situ fraction (percent).
#' @param mNodes Single-case number of positive nodes.
#' @param mMetSize Single-case largest nodal metastasis (mm).
#' @param survivalTime Follow-up time, to relate RCB class to outcome (cohort
#'   mode).
#' @param survivalStatus Event indicator for the survival linkage.
#' @param eventLevel Level of the status variable representing the event.
#' @param showDistribution Tabulate the RCB class distribution across the
#'   cohort.
#' @param showPlot Plot the RCB class distribution (cohort) or the case
#'   position (single case).
#' @param survivalLink If survival time and status are supplied, show a
#'   log-rank test across classes.
#' @param showSummary Plain-language summary of the result.
#' @param showExplanation Explanation of the RCB formula and classes.
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$todo} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$caseTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$distributionTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$survivalTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$plot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$summary} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$explanation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$addIndexToData} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$addClassToData} \tab \tab \tab \tab \tab an output \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$caseTable$asDF}
#'
#' \code{as.data.frame(results$caseTable)}
#'
#' @export
residualcancerburden <- function(
    data,
    inputMode = "data",
    d1 = NULL,
    d2 = NULL,
    cellularity = NULL,
    cis = NULL,
    positiveNodes = NULL,
    metSize = NULL,
    mD1 = 20,
    mD2 = 15,
    mCellularity = 10,
    mCis = 0,
    mNodes = 0,
    mMetSize = 0,
    survivalTime = NULL,
    survivalStatus = NULL,
    eventLevel,
    showDistribution = TRUE,
    showPlot = TRUE,
    survivalLink = FALSE,
    showSummary = FALSE,
    showExplanation = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("residualcancerburden requires jmvcore to be installed (restart may be required)")

    if ( ! missing(d1)) d1 <- jmvcore::resolveQuo(jmvcore::enquo(d1))
    if ( ! missing(d2)) d2 <- jmvcore::resolveQuo(jmvcore::enquo(d2))
    if ( ! missing(cellularity)) cellularity <- jmvcore::resolveQuo(jmvcore::enquo(cellularity))
    if ( ! missing(cis)) cis <- jmvcore::resolveQuo(jmvcore::enquo(cis))
    if ( ! missing(positiveNodes)) positiveNodes <- jmvcore::resolveQuo(jmvcore::enquo(positiveNodes))
    if ( ! missing(metSize)) metSize <- jmvcore::resolveQuo(jmvcore::enquo(metSize))
    if ( ! missing(survivalTime)) survivalTime <- jmvcore::resolveQuo(jmvcore::enquo(survivalTime))
    if ( ! missing(survivalStatus)) survivalStatus <- jmvcore::resolveQuo(jmvcore::enquo(survivalStatus))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(d1), d1, NULL),
            `if`( ! missing(d2), d2, NULL),
            `if`( ! missing(cellularity), cellularity, NULL),
            `if`( ! missing(cis), cis, NULL),
            `if`( ! missing(positiveNodes), positiveNodes, NULL),
            `if`( ! missing(metSize), metSize, NULL),
            `if`( ! missing(survivalTime), survivalTime, NULL),
            `if`( ! missing(survivalStatus), survivalStatus, NULL))


    options <- residualcancerburdenOptions$new(
        inputMode = inputMode,
        d1 = d1,
        d2 = d2,
        cellularity = cellularity,
        cis = cis,
        positiveNodes = positiveNodes,
        metSize = metSize,
        mD1 = mD1,
        mD2 = mD2,
        mCellularity = mCellularity,
        mCis = mCis,
        mNodes = mNodes,
        mMetSize = mMetSize,
        survivalTime = survivalTime,
        survivalStatus = survivalStatus,
        eventLevel = eventLevel,
        showDistribution = showDistribution,
        showPlot = showPlot,
        survivalLink = survivalLink,
        showSummary = showSummary,
        showExplanation = showExplanation)

    analysis <- residualcancerburdenClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

